      "ships": "Validated journey map, prototype screens, OKR-aligned success metric definition"
    },
    {
      "sprint": 2,
      "weeks": "3-4",
      "focus": "Build core self-serve flow backend and frontend happy path, include lightweight onboarding guide",
      "owner": "Engineering Lead",
      "ships": "Working MVP flow for first value with feature flags to iterate"
    },
    {
      "sprint": 3,
      "weeks": "5-6",
      "focus": "End-to-end telemetry, instrumentation, and A/B test framework for copy and steps",
      "owner": "SRE/Analytics Lead",
      "ships": "Telemetry dashboard, SLIs, and alerts; A/B experiment configured"
    },
    {
      "sprint": 4,
      "weeks": "7-8",
      "focus": "Usability polish, edge-case handling, and reduce friction points identified by prototype",
